// Kalp lamba: dört NeoPixel; düğmeyle üç mod (nabız, gökkuşağı, sıcak beyaz).
#include <Adafruit_NeoPixel.h>

const int LED_PIN = 6;
const int LED_SAYISI = 4;   // NeoPixel halkan kaç LED'liyse onu yaz
const int MOD_PIN = 2;

Adafruit_NeoPixel serit(LED_SAYISI, LED_PIN, NEO_GRB + NEO_KHZ800);
int mod = 0;
int sonButon = HIGH;
long gokkusagiFaz = 0;

void setup() {
  Serial.begin(9600);
  serit.begin();
  serit.setBrightness(200);
  pinMode(MOD_PIN, INPUT_PULLUP);
  delay(50);
  sonButon = digitalRead(MOD_PIN);  // açılış durumunu al; sahte ilk basışı önler
  Serial.println("Kalp lamba hazir. Moda bas.");
}

void nabiz() {
  // Sinüsle nefes alan pembe ışık.
  float f = (sin(millis() / 600.0) + 1) / 2;         // 0..1
  int v = 25 + f * 230;
  for (int i = 0; i < LED_SAYISI; i++) {
    serit.setPixelColor(i, serit.Color(v, v / 6, v / 3));  // pembe
  }
}

void gokkusagi() {
  gokkusagiFaz += 256;
  for (int i = 0; i < LED_SAYISI; i++) {
    int ton = (gokkusagiFaz + i * 65536L / LED_SAYISI) % 65536;
    serit.setPixelColor(i, serit.gamma32(serit.ColorHSV(ton)));
  }
}

void sicakBeyaz() {
  for (int i = 0; i < LED_SAYISI; i++) {
    serit.setPixelColor(i, serit.Color(255, 160, 70));
  }
}

void loop() {
  int b = digitalRead(MOD_PIN);
  if (b == LOW && sonButon == HIGH) {
    mod = (mod + 1) % 3;
    Serial.print("Mod: ");
    Serial.println(mod == 0 ? "nabiz" : mod == 1 ? "gokkusagi" : "sicak beyaz");
    delay(40);  // titreşim
  }
  sonButon = b;

  if (mod == 0) nabiz();
  else if (mod == 1) gokkusagi();
  else sicakBeyaz();

  serit.show();
  delay(20);
}
